#include <iostream>

float a,b,c,d,e,i,COST,cost;

int main()
{
    printf("输入已知家居的长、宽、高：（单位为米，用逗号隔开）
");
    scanf("%f,%f,%f",&a,&b,&c); 
    printf("输入已知家居的价格：（单位为元）
");
    scanf("%f",&cost); 
    COST = cost/(2*((a*b)+(a*c)+(b*c)));
    printf("该类家具的单价为：%.2f 元/平方米

",COST); 
    for(i=0;;i++)
    {
        printf("输入该家居的长、宽、高：（单位为米，用逗号隔开）
输入0,0,0以关闭
");
        scanf("%f,%f,%f",&a,&b,&c); 
        if(a==0,b==0,c==0) break;
        d = 2*((a*b)+(a*c)+(b*c))*COST;
        printf("该家居的目前价格为：%.2f 元
",d); 
        e += d;
        printf("以上家居的累计总价为：%.2f 元

",e); 
    }
    return 0;
}
